[CmdletBinding()]
param(
    [ValidateSet('diagnostic', 'load', 'stress')]
    [string]$Mode = 'diagnostic',
    [int]$RequestsPerEndpoint = 0,
    [string]$Concurrency = '',
    [ValidateRange(1024, 65534)]
    [int]$ApiPort = 5091,
    [ValidateRange(1024, 65534)]
    [int]$PostgresPort = 15432,
    [string]$PostgresHost = '127.0.0.1',
    [string]$PostgresContainer = $env:TODIR_PERF_POSTGRES_CONTAINER,
    [string]$PostgresAdminPassword = $env:TODIR_PERF_POSTGRES_ADMIN_PASSWORD,
    [string]$RuntimePassword = $env:TODIR_PERF_RUNTIME_PASSWORD,
    [string]$SeedPassword = $env:TODIR_PERF_SEED_PASSWORD,
    [string]$PreMigrationSql = '',
    [string]$ArtifactDirectory = '',
    [switch]$EnableStatementLogging,
    [switch]$KeepDatabase
)

$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path
. (Join-Path $PSScriptRoot 'platform-performance-helpers.ps1')

if ($KeepDatabase -and $Mode -ne 'diagnostic') { throw '-KeepDatabase is restricted to diagnostic mode.' }
if ([string]::IsNullOrWhiteSpace($PostgresContainer)) { throw "-PostgresContainer is required. It must be a P0-B-owned disposable container labelled todir.perf.disposable=true." }
if ([string]::IsNullOrWhiteSpace($PostgresAdminPassword)) { throw 'PostgresAdminPassword is required through -PostgresAdminPassword or TODIR_PERF_POSTGRES_ADMIN_PASSWORD.' }
if ([string]::IsNullOrWhiteSpace($RuntimePassword)) { throw 'RuntimePassword is required through -RuntimePassword or TODIR_PERF_RUNTIME_PASSWORD.' }
if ([string]::IsNullOrWhiteSpace($SeedPassword)) { throw 'SeedPassword is required through -SeedPassword or TODIR_PERF_SEED_PASSWORD.' }
if ($EnableStatementLogging -and $Mode -ne 'diagnostic') { throw 'Detailed PostgreSQL statement logging is restricted to diagnostic mode.' }
if (-not [string]::IsNullOrWhiteSpace($PreMigrationSql)) {
    $preMigrationPath = (Resolve-Path -LiteralPath $PreMigrationSql -ErrorAction Stop).Path
    $bootstrapPrefix = [IO.Path]::GetFullPath((Join-Path $repo 'backend\DbMigrator\Database\bootstrap')) + [IO.Path]::DirectorySeparatorChar
    if (-not $preMigrationPath.StartsWith($bootstrapPrefix, [StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetFileName($preMigrationPath) -ne 'platform-kernel-forward-fix-openiddict.sql') { throw 'PreMigrationSql is restricted to the known disposable-bootstrap compatibility script.' }
} else { $preMigrationPath = $null }

$profile = Get-ModeProfile -Mode $Mode -RequestsPerEndpoint $RequestsPerEndpoint -Concurrency $Concurrency
$runId = New-RunId
$database = "todir_perf_$runId"
Assert-DisposableDatabaseName $database
$apiBaseUrl = "http://127.0.0.1:$ApiPort"
$artifactRoot = if ([string]::IsNullOrWhiteSpace($ArtifactDirectory)) { Join-Path $repo 'artifacts\performance' } else { $resolvedArtifactPath = Resolve-Path -LiteralPath $ArtifactDirectory -ErrorAction SilentlyContinue; if ($null -ne $resolvedArtifactPath) { $resolvedArtifactPath.Path } else { $null } }
if ([string]::IsNullOrWhiteSpace($artifactRoot)) { $artifactRoot = [IO.Path]::GetFullPath($ArtifactDirectory) }
$repoPrefix = [IO.Path]::GetFullPath($repo) + [IO.Path]::DirectorySeparatorChar
if (-not ([IO.Path]::GetFullPath($artifactRoot)).StartsWith($repoPrefix, [StringComparison]::OrdinalIgnoreCase)) { throw 'ArtifactDirectory must be inside the repository.' }
New-Item -ItemType Directory -Path $artifactRoot -Force | Out-Null
$resultPath = Join-Path $artifactRoot "platform-performance-$database.json"
$failurePath = Join-Path $artifactRoot "platform-performance-$database.failure.json"
$apiProcesses = @(); $sessions = @(); $sampleJobs = @(); $today = (Get-Date).ToString('yyyy-MM-dd'); $ids = @(); $cleanupErrors = @(); $benchmarkFailure = $null; $logStatementChanged = $false
$environmentKeys = @('ASPNETCORE_ENVIRONMENT','DOTNET_ENVIRONMENT','TODIR_REPOSITORY_ROOT','TODIR_MIGRATOR_CONNECTION','TODIR_RUNTIME_PASSWORD','SEED_DEFAULT_PASSWORD','TODIR_DATABASE_CONNECTION','TODIR_METRICS_ENABLED','TODIR_AUTHORIZATION_REQUEST_CACHE_ENABLED','TODIR_PERFORMANCE_SQL_COUNT','TODIR_RATE_LIMIT_API_PERMITS','TODIR_RATE_LIMIT_AUTH_PERMITS','TODIR_FILE_LOGGING_ENABLED','TODIR_RABBITMQ_HOST')
$savedEnvironment = @{}
foreach ($key in $environmentKeys) { $item = Get-Item "Env:$key" -ErrorAction SilentlyContinue; $savedEnvironment[$key] = [pscustomobject]@{ Exists = ($null -ne $item); Value = if ($null -ne $item) { $item.Value } else { $null } } }

function Invoke-Docker { param([Parameter(Mandatory)][string[]]$Arguments); $output = & docker @Arguments; if ($LASTEXITCODE -ne 0) { throw "Docker command failed: docker $($Arguments -join ' ')" }; return @($output) }
function Get-DisposableContainer {
    $raw = Invoke-Docker @('inspect', $PostgresContainer); $inspect = ($raw -join "`n") | ConvertFrom-Json
    if (@($inspect).Count -ne 1) { throw "Expected exactly one inspected container for '$PostgresContainer'." }
    Assert-DisposableContainerMetadata $inspect[0] | Out-Null
    $ports = $inspect[0].NetworkSettings.Ports.'5432/tcp'
    if ($null -eq $ports -or @($ports).Count -eq 0 -or [string]$ports[0].HostPort -ne [string]$PostgresPort) { throw "Container '$PostgresContainer' is not mapped to localhost port $PostgresPort." }
    return $inspect[0]
}
function Assert-HostPortAvailable { param([int]$Port); $existing = @(Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue); if ($existing.Count -gt 0) { throw "Required local TCP port $Port is already listening." } }
function Invoke-Postgres { param([Parameter(Mandatory)][string]$TargetDatabase, [Parameter(Mandatory)][string]$Sql); Assert-DisposableDatabaseName $database; return ((Invoke-Docker @('exec',$PostgresContainer,'psql','-U','postgres','-d',$TargetDatabase,'-v','ON_ERROR_STOP=1','-t','-A','-c',$Sql)) -join "`n").Trim() }
function Get-PostgresJson { param([Parameter(Mandatory)][string]$Sql); $value = Invoke-Postgres -TargetDatabase $database -Sql $Sql; if ([string]::IsNullOrWhiteSpace($value)) { return $null }; return $value | ConvertFrom-Json }
function Get-DbSnapshot { return Get-PostgresJson "select json_build_object('connections',count(*),'active',count(*) filter(where state='active'),'idleInTransaction',count(*) filter(where state='idle in transaction'),'lockWaits',count(*) filter(where wait_event_type='Lock'),'maxTransactionSeconds',coalesce(max(extract(epoch from(clock_timestamp()-xact_start))) filter(where xact_start is not null),0)) from pg_stat_activity where datname='$database'" }
function Get-DatabaseTransactionSnapshot { return Get-PostgresJson "select json_build_object('commits',xact_commit,'rollbacks',xact_rollback,'blocksRead',blks_read,'blocksHit',blks_hit) from pg_stat_database where datname='$database'" }
function Get-LogStatementCount { param([DateTimeOffset]$Since); if (-not $EnableStatementLogging) { return $null }; $raw = Invoke-Docker @('logs','--since',$Since.UtcDateTime.ToString('o'),$PostgresContainer); $count = [int](@($raw | Where-Object { $_ -match '(statement:|execute [^:]+:|duration:)' }).Count); if ($count -eq 0) { return $null }; return $count }
function Get-DatasetSnapshot { return Get-PostgresJson "select json_build_object('tenants',(select count(*) from platform.tenant),'legalEntities',(select count(*) from platform.legal_entity),'branches',(select count(*) from platform.branch),'parties',(select count(*) from foundation_directory.party),'openItems',(select count(*) from finance_subledger.party_open_item where is_open=true),'productVariants',(select count(*) from foundation_catalog.product_variant),'projects',(select count(*) from business_projects.project))" }

function Invoke-HttpJson {
    param($Session,[ValidateSet('Get','Post','Put','Patch','Delete')][string]$Method,[string]$Url,[object]$Body=$null)
    $request = [System.Net.Http.HttpRequestMessage]::new([System.Net.Http.HttpMethod]::$Method,$Url)
    if ($Method -ne 'Get' -and $Session.PSObject.Properties.Name -contains 'CsrfToken') { [void]$request.Headers.TryAddWithoutValidation('X-CSRF-TOKEN',$Session.CsrfToken) }
    if ($null -ne $Body) { $request.Content = [System.Net.Http.StringContent]::new(($Body|ConvertTo-Json -Compress -Depth 12),[Text.Encoding]::UTF8,'application/json') }
    $watch = [Diagnostics.Stopwatch]::StartNew()
    try { $response=$Session.Client.SendAsync($request).GetAwaiter().GetResult();$content=$response.Content.ReadAsStringAsync().GetAwaiter().GetResult();$watch.Stop();[pscustomobject]@{StatusCode=[int]$response.StatusCode;Content=$content;Milliseconds=[Math]::Round($watch.Elapsed.TotalMilliseconds,2);Success=([int]$response.StatusCode-ge 200-and[int]$response.StatusCode-lt 300);ErrorCategory=if([int]$response.StatusCode-ge 500){'Http5xx'}elseif([int]$response.StatusCode-ge 400){'Http4xx'}else{$null}} }
    catch [System.Threading.Tasks.TaskCanceledException] { $watch.Stop();[pscustomobject]@{StatusCode=0;Content=$_.Exception.Message;Milliseconds=[Math]::Round($watch.Elapsed.TotalMilliseconds,2);Success=$false;ErrorCategory='Timeout'} }
    catch { $watch.Stop();[pscustomobject]@{StatusCode=0;Content=$_.Exception.Message;Milliseconds=[Math]::Round($watch.Elapsed.TotalMilliseconds,2);Success=$false;ErrorCategory='Transport'} }
    finally { $request.Dispose() }
}
function Wait-Api { param([string]$BaseUrl,[string]$ErrorLog); for($attempt=1;$attempt-le90;$attempt++){try{if((Invoke-WebRequest -Uri "$BaseUrl/health" -UseBasicParsing -TimeoutSec 2).StatusCode-eq 200){return}}catch{};Start-Sleep -Milliseconds 400};throw "API did not become healthy at $BaseUrl. See $ErrorLog" }
function Start-Api {
    param([int]$Port,[bool]$CacheEnabled)
    Assert-HostPortAvailable $Port
    $stdout=Join-Path $artifactRoot "api-$database-$Port.out.log";$stderr=Join-Path $artifactRoot "api-$database-$Port.err.log"
    $env:ASPNETCORE_ENVIRONMENT='Development';$env:DOTNET_ENVIRONMENT='Development';$env:TODIR_DATABASE_CONNECTION="Host=$PostgresHost;Port=$PostgresPort;Database=$database;Username=erp_app;Password=$RuntimePassword;Include Error Detail=true;Maximum Pool Size=64;Application Name=platform-perf-api-$Port";$env:TODIR_METRICS_ENABLED='true';$env:TODIR_AUTHORIZATION_REQUEST_CACHE_ENABLED=$CacheEnabled.ToString().ToLowerInvariant();$env:TODIR_PERFORMANCE_SQL_COUNT='true';$env:TODIR_RATE_LIMIT_API_PERMITS='100000';$env:TODIR_RATE_LIMIT_AUTH_PERMITS='100000';$env:TODIR_FILE_LOGGING_ENABLED='false';$env:TODIR_RABBITMQ_HOST=''
    $dll=Join-Path $repo 'backend\Api\bin\Release\net10.0\Api.dll';if(-not(Test-Path $dll)){throw "Build the Release API before the benchmark: $dll"};$process=Start-Process dotnet -ArgumentList @($dll,'--urls',"http://127.0.0.1:$Port") -WorkingDirectory $repo -RedirectStandardOutput $stdout -RedirectStandardError $stderr -WindowStyle Hidden -PassThru;$script:apiProcesses+=$process;Wait-Api -BaseUrl "http://127.0.0.1:$Port" -ErrorLog $stderr;return $process
}
function Stop-ProcessSafe { param($Process);if($null-ne$Process-and-not$Process.HasExited){try{$Process.CloseMainWindow()|Out-Null}catch{};if(-not$Process.WaitForExit(10000)){Stop-Process -Id $Process.Id -Force -ErrorAction SilentlyContinue}} }
function New-Session {
    param([string]$BaseUrl,[string]$Email)
    $handler=[System.Net.Http.HttpClientHandler]::new();$handler.UseCookies=$true;$client=[System.Net.Http.HttpClient]::new($handler);$client.Timeout=[TimeSpan]::FromSeconds(45);$session=[pscustomobject]@{BaseUrl=$BaseUrl;Handler=$handler;Client=$client;CookieHeader=$null;Context=$null;Email=$Email;CsrfToken=$null}
    $csrf=Invoke-HttpJson $session Get "$BaseUrl/api/v1/auth/csrf";if(-not$csrf.Success){throw "CSRF failed for ${Email}: $($csrf.Content)"};$token=($csrf.Content|ConvertFrom-Json).token
    $request=[System.Net.Http.HttpRequestMessage]::new([System.Net.Http.HttpMethod]::Post,"$BaseUrl/api/v1/auth/login");$request.Headers.Add('X-CSRF-TOKEN',$token);$request.Content=[System.Net.Http.StringContent]::new((@{email=$Email;password=$SeedPassword}|ConvertTo-Json -Compress),[Text.Encoding]::UTF8,'application/json');$login=$client.SendAsync($request).GetAwaiter().GetResult();$loginContent=$login.Content.ReadAsStringAsync().GetAwaiter().GetResult();$request.Dispose();if([int]$login.StatusCode-ne 200){throw "Login failed for ${Email}: $loginContent"};$session.CsrfToken=$token
    $csrfAfter=Invoke-HttpJson $session Get "$BaseUrl/api/v1/auth/csrf";if($csrfAfter.Success){$session.CsrfToken=($csrfAfter.Content|ConvertFrom-Json).token};$context=Invoke-HttpJson $session Get "$BaseUrl/api/v1/session/context";if(-not$context.Success){throw "Session context failed for ${Email}: $($context.Content)"};$session.Context=$context.Content|ConvertFrom-Json;$session.CookieHeader=@($handler.CookieContainer.GetCookies([Uri]$BaseUrl)|ForEach-Object{"$($_.Name)=$($_.Value)"})-join '; ';if([string]::IsNullOrWhiteSpace($session.CookieHeader)){throw "No auth cookie for ${Email}"};return $session
}

function Start-ResourceSampler {
    param([int]$ProcessId,[string]$Name);$path=Join-Path $artifactRoot "resource-$database-$Name.csv";$job=Start-Job -ArgumentList $ProcessId,$path -ScriptBlock {param($PidToSample,$OutputPath);'TimestampUtc,Pid,WorkingSetBytes,PrivateMemoryBytes,ProcessorTimeMs'|Set-Content $OutputPath;while($true){try{$p=Get-Process -Id $PidToSample -ErrorAction Stop;Add-Content $OutputPath ("{0},{1},{2},{3},{4}"-f [DateTimeOffset]::UtcNow.ToString('o'),$p.Id,$p.WorkingSet64,$p.PrivateMemorySize64,[int]$p.TotalProcessorTime.TotalMilliseconds)}catch{break};Start-Sleep -Milliseconds 100}};$script:sampleJobs+=$job
}
function Start-PgSampler {
    $path=Join-Path $artifactRoot "postgres-$database.csv";$containerName=$PostgresContainer;$job=Start-Job -ArgumentList $database,$path,$containerName -ScriptBlock {param($Db,$OutputPath,$Container);'TimestampUtc,Connections,Active,LockWaits,MaxTransactionSeconds'|Set-Content $OutputPath;while($true){try{$line=&docker exec $Container psql -U postgres -d $Db -t -A -F ',' -c "select count(*),count(*) filter(where state='active'),count(*) filter(where wait_event_type='Lock'),coalesce(max(extract(epoch from(clock_timestamp()-xact_start))) filter(where xact_start is not null),0) from pg_stat_activity where datname='$Db'" 2>$null;if($line){Add-Content $OutputPath (("{0},"-f [DateTimeOffset]::UtcNow.ToString('o'))+($line-join''))}}catch{break};Start-Sleep -Milliseconds 150}};$script:sampleJobs+=$job
}
function Start-DockerSampler {
    $path=Join-Path $artifactRoot "docker-$database.csv";$containerName=$PostgresContainer;$job=Start-Job -ArgumentList $path,$containerName -ScriptBlock {param($OutputPath,$Container);'TimestampUtc,Container,CPUPerc,MemUsage,MemPerc,NetIO,BlockIO'|Set-Content $OutputPath;while($true){try{$json=&docker stats $Container --no-stream --format '{{json .}}' 2>$null;if($json){$s=$json|ConvertFrom-Json;Add-Content $OutputPath ("{0},{1},{2},{3},{4},{5},{6}"-f [DateTimeOffset]::UtcNow.ToString('o'),$s.Name,$s.CPUPerc,$s.MemUsage,$s.MemPerc,$s.NetIO,$s.BlockIO)}}catch{break};Start-Sleep -Seconds 1}};$script:sampleJobs+=$job
}
function Stop-Samplers { foreach($job in @($sampleJobs)){Stop-Job $job -ErrorAction SilentlyContinue;Receive-Job $job -ErrorAction SilentlyContinue|Out-Null;Remove-Job $job -Force -ErrorAction SilentlyContinue};$script:sampleJobs=@() }
function Get-ResourcePeak { param([string]$Name);$path=Join-Path $artifactRoot "resource-$database-$Name.csv";if(-not(Test-Path $path)){return $null};$rows=@(Import-Csv $path);if($rows.Count-eq 0){return $null};[pscustomobject]@{Process=$Name;Samples=$rows.Count;PeakWorkingSetMiB=[Math]::Round((@($rows|ForEach-Object{[double]$_.WorkingSetBytes}|Measure-Object -Maximum).Maximum/1MB),2);PeakPrivateMiB=[Math]::Round((@($rows|ForEach-Object{[double]$_.PrivateMemoryBytes}|Measure-Object -Maximum).Maximum/1MB),2);ProcessorTimeMs=[int](($rows|Select-Object -Last 1).ProcessorTimeMs-($rows|Select-Object -First 1).ProcessorTimeMs)} }
function Get-ContainerResourceSamples { $path=Join-Path $artifactRoot "docker-$database.csv";if(-not(Test-Path $path)){return @()};return @(Import-Csv $path) }

function Invoke-ParallelRequests {
    param([string]$Url,[string]$CookieHeader,[string]$CsrfToken,[int]$Count,[int]$Level,[ValidateSet('Get','Post')][string]$Method='Get',[string]$BodyTemplate='')
    $items=1..$Count|ForEach-Object -Parallel { $template=$using:BodyTemplate;$method=$using:Method;$watch=[Diagnostics.Stopwatch]::StartNew();$headers=@{Cookie=$using:CookieHeader};if($method-ne'Get'){$headers['X-CSRF-TOKEN']=$using:CsrfToken};$body=if($method-eq'Post'){$template.Replace('__INDEX__',[string]$_)}else{$null};try{$response=Invoke-WebRequest -Uri $using:Url -Method $method -Headers $headers -Body $body -ContentType 'application/json' -UseBasicParsing -TimeoutSec 45 -SkipHttpErrorCheck;$watch.Stop();$commandHeader=@($response.Headers['X-Todir-Db-Commands'])|Select-Object -First 1;[pscustomobject]@{StatusCode=[int]$response.StatusCode;Milliseconds=[Math]::Round($watch.Elapsed.TotalMilliseconds,2);Success=([int]$response.StatusCode-ge 200-and[int]$response.StatusCode-lt 300);ErrorCategory=if([int]$response.StatusCode-ge 500){'Http5xx'}elseif([int]$response.StatusCode-ge 400){'Http4xx'}else{$null};DbCommands=if($null-ne$commandHeader-and$commandHeader-ne''){[int]$commandHeader}else{$null}}}catch [System.Threading.Tasks.TaskCanceledException]{$watch.Stop();[pscustomobject]@{StatusCode=0;Milliseconds=[Math]::Round($watch.Elapsed.TotalMilliseconds,2);Success=$false;ErrorCategory='Timeout';DbCommands=$null}}catch{$watch.Stop();[pscustomobject]@{StatusCode=0;Milliseconds=[Math]::Round($watch.Elapsed.TotalMilliseconds,2);Success=$false;ErrorCategory='Transport';DbCommands=$null}} } -ThrottleLimit $Level
    return @($items)
}
function Get-ResultSummary {
    param([string]$Kind,[string]$Module,[string]$Operation,[string]$Tenant,[int]$Level,[object[]]$Results,[double]$ElapsedSeconds,[object]$BeforeDb,[object]$AfterDb,[object]$BeforeTx,[object]$AfterTx,[int]$WarmupCount)
    $latency=Get-LatencySummary -Values @($Results|ForEach-Object{[double]$_.Milliseconds});$errors=Get-ErrorSummary -Results $Results
    $commandValues=@($Results|Where-Object{$null-ne$_.DbCommands}|ForEach-Object{[int]$_.DbCommands});$commandTotal=if($commandValues.Count-gt 0){[int](($commandValues|Measure-Object -Sum).Sum)}else{$null};[pscustomobject]@{Kind=$Kind;Module=$Module;Tenant=$Tenant;Operation=$Operation;Concurrency=$Level;Requests=$errors.Requests;Successes=$errors.Successes;Errors=$errors.Errors;ErrorRate=$errors.ErrorRate;ErrorDistribution=$errors.ErrorDistribution;WarmupRequests=$WarmupCount;MeasurementSeconds=[Math]::Round($ElapsedSeconds,3);Rps=if($ElapsedSeconds-gt 0){[Math]::Round($errors.Requests/$ElapsedSeconds,2)}else{$null};SampleCount=$latency.SampleCount;P50Ms=$latency.P50Ms;P50Status=$latency.P50Status;P95Ms=$latency.P95Ms;P95Status=$latency.P95Status;P99Ms=$latency.P99Ms;P99Status=$latency.P99Status;MaxMs=$latency.MaxMs;SqlStatements=$commandTotal;SqlStatementsPerRequest=if($null-ne$commandTotal-and$errors.Requests-gt 0){[Math]::Round($commandTotal/$errors.Requests,2)}else{$null};Transactions=if($null-ne$BeforeTx-and$null-ne$AfterTx){[int](($AfterTx.commits+$AfterTx.rollbacks)-($BeforeTx.commits+$BeforeTx.rollbacks))}else{$null};Connections=if($null-ne$AfterDb){[int]$AfterDb.connections}else{$null};Active=if($null-ne$AfterDb){[int]$AfterDb.active}else{$null};LockWaits=if($null-ne$AfterDb){[int]$AfterDb.lockWaits}else{$null};MaxTransactionSeconds=if($null-ne$AfterDb){[double]$AfterDb.maxTransactionSeconds}else{$null}}
}
function Invoke-ReadBenchmark {
    param([string]$Module,[string]$Name,[string]$Url,$Session,[string]$Tenant,[int]$Level)
    $warmup=Invoke-ParallelRequests -Url $Url -CookieHeader $Session.CookieHeader -CsrfToken $Session.CsrfToken -Count $profile.WarmupRequests -Level ([Math]::Min($Level,$profile.WarmupRequests));$beforeTx=Get-DatabaseTransactionSnapshot;$beforeDb=Get-DbSnapshot;$since=[DateTimeOffset]::UtcNow;$watch=[Diagnostics.Stopwatch]::StartNew();$results=Invoke-ParallelRequests -Url $Url -CookieHeader $Session.CookieHeader -CsrfToken $Session.CsrfToken -Count $profile.RequestsPerEndpoint -Level $Level;$watch.Stop();$afterTx=Get-DatabaseTransactionSnapshot;$afterDb=Get-DbSnapshot;$logCount=Get-LogStatementCount $since;$summary=Get-ResultSummary -Kind 'read' -Module $Module -Operation $Name -Tenant $Tenant -Level $Level -Results $results -ElapsedSeconds $watch.Elapsed.TotalSeconds -BeforeDb $beforeDb -AfterDb $afterDb -BeforeTx $beforeTx -AfterTx $afterTx -WarmupCount $warmup.Count;if($null-ne$logCount){$summary|Add-Member -NotePropertyName LogStatementCount -NotePropertyValue $logCount};return $summary
}
function Invoke-WriteBenchmark {
    param($Session,[string]$EntityId,[string]$Tenant,[int]$Level)
    $body=(@{legalEntityId=$EntityId;name="Performance load __INDEX__ $runId";projectType='InternalProject';startDate=$today;billingModel='NonBillable';currencyCode='EGP'}|ConvertTo-Json -Compress);$url="$($Session.BaseUrl)/api/v1/projects/legal-entities/$EntityId";$warmup=Invoke-ParallelRequests -Url $url -CookieHeader $Session.CookieHeader -CsrfToken $Session.CsrfToken -Count 1 -Level 1 -Method Post -BodyTemplate $body;$beforeTx=Get-DatabaseTransactionSnapshot;$beforeDb=Get-DbSnapshot;$watch=[Diagnostics.Stopwatch]::StartNew();$results=Invoke-ParallelRequests -Url $url -CookieHeader $Session.CookieHeader -CsrfToken $Session.CsrfToken -Count $profile.RequestsPerEndpoint -Level $Level -Method Post -BodyTemplate $body;$watch.Stop();$afterTx=Get-DatabaseTransactionSnapshot;$afterDb=Get-DbSnapshot;return Get-ResultSummary -Kind 'write' -Module 'Projects' -Operation 'create-draft-sustained' -Tenant $Tenant -Level $Level -Results $results -ElapsedSeconds $watch.Elapsed.TotalSeconds -BeforeDb $beforeDb -AfterDb $afterDb -BeforeTx $beforeTx -AfterTx $afterTx -WarmupCount $warmup.Count
}
function Invoke-WriteSmoke {
    param($Session,[string]$TenantLabel,[string]$EntityId,[hashtable]$Identifiers)
    $stamp=[Guid]::NewGuid().ToString('N').Substring(0,8);$operations=@(
        @{Module='Projects';Name='create-draft';Url="$($Session.BaseUrl)/api/v1/projects/legal-entities/$EntityId";Body=@{legalEntityId=$EntityId;name="Performance probe $stamp";projectType='InternalProject';startDate=$today;billingModel='NonBillable';currencyCode='EGP'}},
        @{Module='Sales';Name='create-quotation-draft';Url="$($Session.BaseUrl)/api/v1/sales/legal-entities/$EntityId/quotations";Body=@{legalEntityId=$EntityId;partyId=$Identifiers.Party;currencyCode='EGP';quoteDate=$today;validUntil=$today;lines=@(@{productVariantId=$Identifiers.Variant;description='Performance probe';quantity=1;unitPrice=1})}},
        @{Module='Invoicing';Name='create-customer-draft';Url="$($Session.BaseUrl)/api/v1/invoicing/customer-invoices";Body=@{legalEntityId=$EntityId;partyId=$Identifiers.Party;documentDate=$today;postingDate=$today;taxDate=$today;currencyCode='EGP';paymentTermId=$null;lines=@(@{productVariantId=$Identifiers.Variant;description='Performance probe';quantity='1'})}},
        @{Module='Inventory';Name='create-warehouse';Url="$($Session.BaseUrl)/api/v1/inventory/legal-entities/$EntityId/warehouses";Body=@{code="PERF_$stamp";name='Performance probe';locationMode='WarehouseOnly';branchId=$Identifiers.Branch}},
        @{Module='POS';Name='create-cart';Url="$($Session.BaseUrl)/api/v1/pos/carts";Body=@{sessionId=$Identifiers.Session;currencyCode='EGP';customerPartyId=$Identifiers.Party}},
        @{Module='HR';Name='create-employee';Url="$($Session.BaseUrl)/api/v1/hr/employees";Body=@{arabicName="اختبار أداء $stamp";englishName="Performance $stamp";legalEntityId=$EntityId;employmentType='FullTime';startDate=$today}},
        @{Module='Payroll';Name='create-component';Url="$($Session.BaseUrl)/api/v1/payroll/legal-entities/$EntityId/components";Body=@{code="PERF_$stamp";name='Performance probe';category='Earning';direction='Credit';inputMode='Manual'}},
        @{Module='Payments';Name='create-account';Url="$($Session.BaseUrl)/api/v1/payments/legal-entities/$EntityId/accounts";Body=@{legalEntityId=$EntityId;branchId=$Identifiers.Branch;code="PERF_$stamp";name='Performance probe';type='Cashbox';currencyPolicy='SingleCurrency';currencyCode='EGP';bankName=$null;accountHolder=$null;maskedIdentifier=$null;secretRef=$null}}
    );foreach($operation in $operations){$response=Invoke-HttpJson $Session Post $operation.Url $operation.Body;[pscustomobject]@{Kind='write-smoke';Tenant=$TenantLabel;Module=$operation.Module;Operation=$operation.Name;StatusCode=$response.StatusCode;Success=$response.Success;Milliseconds=$response.Milliseconds;ErrorCategory=$response.ErrorCategory;Error=if(-not$response.Success){$response.Content.Substring(0,[Math]::Min(300,$response.Content.Length))}else{$null}}}
}
function Invoke-FunctionalSmoke { param([object[]]$Operations,$Session,[string]$EntityId,[string]$Tenant);$results=@();foreach($operation in $Operations){if($operation.Module-eq'Subledger'-and$Tenant-ne'atlas'){continue};$path=if($operation.Path-match'\{0\}'){$operation.Path-f $EntityId}else{$operation.Path};$response=Invoke-HttpJson $Session Get "$($Session.BaseUrl)$path";$json=$false;if($response.Success){try{$null=$response.Content|ConvertFrom-Json;$json=$true}catch{$json=$false}};$results+=[pscustomobject]@{Tenant=$Tenant;Module=$operation.Module;Operation=$operation.Name;StatusCode=$response.StatusCode;Success=($response.Success-and$json);JsonShape=$json;ErrorCategory=if($response.Success-and-not$json){'InvalidJson'}else{$response.ErrorCategory}}};return $results }
function Invoke-SecuritySmoke { param($Atlas,$Delta,[string]$AtlasEntity,[string]$DeltaEntity);$unauthenticated=Invoke-WebRequest -Uri "$($Atlas.BaseUrl)/api/v1/projects/legal-entities/$($AtlasEntity)?page=1&pageSize=1" -UseBasicParsing -TimeoutSec 45 -SkipHttpErrorCheck;$deltaOnAtlas=Invoke-HttpJson $Delta Get "$($Delta.BaseUrl)/api/v1/projects/legal-entities/$($AtlasEntity)?page=1&pageSize=1";$atlasOnDelta=Invoke-HttpJson $Atlas Get "$($Atlas.BaseUrl)/api/v1/projects/legal-entities/$($DeltaEntity)?page=1&pageSize=1";return @([pscustomobject]@{Check='unauthenticated-request';StatusCode=[int]$unauthenticated.StatusCode;Passed=([int]$unauthenticated.StatusCode-ge 401-and[int]$unauthenticated.StatusCode-lt 500)},[pscustomobject]@{Check='cross-tenant-delta-to-atlas';StatusCode=$deltaOnAtlas.StatusCode;Passed=(-not$deltaOnAtlas.Success)},[pscustomobject]@{Check='cross-tenant-atlas-to-delta';StatusCode=$atlasOnDelta.StatusCode;Passed=(-not$atlasOnDelta.Success)}) }
function Get-QueryPlans { param([string]$AtlasTenant,[string]$AtlasEntity,[string]$Party);$queries=[ordered]@{'sales.quotations.list'="explain (analyze,buffers,format json) select id,party_id,state from business_sales.quotation where tenant_id='$AtlasTenant' and legal_entity_id='$AtlasEntity' order by id limit 50";'inventory.stock_balance.list'="explain (analyze,buffers,format json) select product_variant_id,warehouse_id,on_hand_base_quantity,reserved_base_quantity from business_inventory.stock_balance where tenant_id='$AtlasTenant' and legal_entity_id='$AtlasEntity' order by id limit 50";'projects.list'="explain (analyze,buffers,format json) select id,project_number,name,lifecycle_state from business_projects.project where tenant_id='$AtlasTenant' and legal_entity_id='$AtlasEntity' order by id limit 50";'subledger.open_items.exposure'="explain (analyze,buffers,format json) select id,open_transaction_amount,base_currency from finance_subledger.party_open_item where tenant_id='$AtlasTenant' and legal_entity_id='$AtlasEntity' and party_id='$Party' and is_open=true order by id"};$plans=@();foreach($query in $queries.GetEnumerator()){$plans+=[pscustomobject]@{Query=$query.Key;Plan=(Invoke-Postgres $database $query.Value|ConvertFrom-Json)}};return $plans }
function Set-BenchmarkEnvironment { $env:DOTNET_ENVIRONMENT='Development';$env:ASPNETCORE_ENVIRONMENT='Development';$env:TODIR_REPOSITORY_ROOT=$repo;$env:TODIR_MIGRATOR_CONNECTION="Host=$PostgresHost;Port=$PostgresPort;Database=$database;Username=postgres;Password=$PostgresAdminPassword;Include Error Detail=true";$env:TODIR_RUNTIME_PASSWORD=$RuntimePassword;$env:SEED_DEFAULT_PASSWORD=$SeedPassword }
function Restore-BenchmarkEnvironment { foreach($key in $environmentKeys){$saved=$savedEnvironment[$key];if($saved.Exists){Set-Item "Env:$key" $saved.Value}else{Remove-Item "Env:$key" -ErrorAction SilentlyContinue}} }
function Write-Report { param([object]$Report,[string]$Path=$resultPath);$Report|ConvertTo-Json -Depth 30|Set-Content -LiteralPath $Path -Encoding utf8 }

